-- 打卡当日的待办与自动化任务（演示数据由 _verify/gen-daytask.cjs 生成，随机种子 20261106）
drop table if exists erp_day_task;
create table erp_day_task (
  day_task_id   bigint       not null auto_increment comment '任务ID',
  task_date     date         not null comment '归属日期',
  task_type     varchar(16)  not null comment 'TODO 待办 / AUTOMATION 自动化',
  title         varchar(200) not null comment '任务标题',
  detail        varchar(500) default null comment '执行详情或失败原因',
  status        varchar(16)  not null comment 'PENDING 待处理 / RUNNING 进行中 / DONE 完成 / FAILED 失败',
  owner         varchar(64)  default null comment '负责人',
  ref_code      varchar(64)  default null comment '关联单号',
  started_time  datetime     default null comment '开始时间',
  finished_time datetime     default null comment '结束时间',
  create_time   datetime     default current_timestamp comment '创建时间',
  primary key (day_task_id),
  key idx_day_task_date (task_date, status)
) engine=innodb auto_increment=1 default charset=utf8mb4 comment='按日的待办与自动化任务';

